// Node.js Backend Example: Sanitizing Input to prevent XSS

const DOMPurify = require('dompurify');

app.post('/api/comments', (req, res) => {
  const rawComment = req.body.text;
  // User sends: "Hello <script>alert('Hacked!')</script>"

  // 1. Sanitize the input before saving to the database!
  // This strips out all dangerous HTML tags and leaves the safe text.
  const safeComment = DOMPurify.sanitize(rawComment);
  // Result: "Hello "

  db.comments.save(safeComment);
